// @generated by @frameless/qwik; do not edit.
import { $, component$, sync$, useComputed$, useSignal, useStore } from '@qwik.dev/core';

export const TodoMvc = component$(
	(props: {
		onTrace$: (name: string, detail: Record<string, unknown>, event: unknown) => void;
	}) => {
		const todos = useStore([
			{ id: 't1', title: 'Taste JavaScript', done: true },
			{ id: 't2', title: 'Buy a unicorn', done: false },
		]);
		const draft = useSignal('');
		const next = useSignal(3);
		const filter = useSignal('all');
		const editing = useSignal('');
		const editDraft = useSignal('');
		const active = useComputed$(() => todos.filter((todo) => !todo.done).length);
		const completed = useComputed$(() => todos.filter((todo) => todo.done).length);
		const allDone = useComputed$(
			() => todos.length > 0 && todos.filter((todo) => !todo.done).length === 0,
		);
		const remainingLabel = useComputed$(() =>
			todos.filter((todo) => !todo.done).length === 1 ? ' item left' : ' items left',
		);
		return (
			<section class="todoapp" data-app="todomvc">
				<header class="header">
					<h1>todos</h1>
					<form
						class="new-todo-form"
						data-action="add"
						onClick$={async (event) => {
							await props.onTrace$('press', { area: 'new-todo' }, event);
						}}
						onSubmit$={[
							sync$((event) => {
								event.preventDefault();
							}),
							$(async (event) => {
								const title = draft.value.trim();
								const item = { id: `t${next.value}`, title, done: false };
								todos.splice(
									0,
									todos.length,
									...(title === '' ? todos : todos.concat(item)),
								);
								next.value = title === '' ? next.value : next.value + 1;
								draft.value = '';
								await props.onTrace$('add', { id: item.id, title }, event);
							}),
						]}
					>
						<input
							class="new-todo"
							placeholder="What needs to be done?"
							data-action="new"
							value={draft.value}
							onInput$={(event, element) => {
								draft.value = element.value;
							}}
						/>
					</form>
				</header>
				{todos.length > 0 ? (
					<main class="main">
						<input
							id="toggle-all"
							class="toggle-all"
							type="checkbox"
							data-action="toggle-all"
							checked={allDone.value}
							onChange$={async (event, element) => {
								const done = element.checked;
								todos.splice(
									0,
									todos.length,
									...todos.map((todo) => ({
										id: todo.id,
										title: todo.title,
										done,
									})),
								);
								await props.onTrace$('toggle-all', { done }, event);
							}}
						/>
						<label for="toggle-all">Mark all as complete</label>
						<ul class="todo-list">
							{todos.map((todo) => (
								<li
									key={todo.id}
									class={
										editing.value === todo.id
											? 'editing'
											: todo.done
												? 'completed'
												: ''
									}
									data-oracle-todo-key={todo.id}
									hidden={
										filter.value === 'active'
											? todo.done
											: filter.value === 'completed'
												? !todo.done
												: false
									}
								>
									{editing.value === todo.id ? (
										<form
											class="edit-form"
											data-commit={todo.id}
											onClick$={async (event) => {
												await props.onTrace$(
													'press',
													{ area: 'edit' },
													event,
												);
											}}
											onSubmit$={[
												sync$((event) => {
													event.preventDefault();
												}),
												$(async (event) => {
													const title = editDraft.value.trim();
													todos.splice(
														0,
														todos.length,
														...(title === ''
															? todos
															: todos.map((entry) =>
																	entry.id === todo.id
																		? {
																				id: entry.id,
																				title,
																				done: entry.done,
																			}
																		: entry,
																)),
													);
													editing.value = '';
													editDraft.value = '';
													await props.onTrace$(
														'commit',
														{ id: todo.id, title },
														event,
													);
												}),
											]}
										>
											<input
												class="edit"
												data-edit={todo.id}
												value={editDraft.value}
												onInput$={(event, element) => {
													editDraft.value = element.value;
												}}
											/>
											<button
												type="button"
												class="cancel-edit"
												data-revert={todo.id}
												onClick$={async (event) => {
													editing.value = '';
													editDraft.value = '';
													await props.onTrace$(
														'revert',
														{ id: todo.id },
														event,
													);
												}}
											>
												cancel
											</button>
										</form>
									) : (
										<div class="view">
											<input
												class="toggle"
												type="checkbox"
												data-toggle={todo.id}
												checked={todo.done}
												onChange$={async (event, element) => {
													const done = element.checked;
													todos.splice(
														0,
														todos.length,
														...todos.map((entry) =>
															entry.id === todo.id
																? {
																		id: entry.id,
																		title: entry.title,
																		done,
																	}
																: entry,
														),
													);
													await props.onTrace$(
														'toggle',
														{ id: todo.id, done },
														event,
													);
												}}
											/>
											<button
												type="button"
												class="todo-title"
												data-title={todo.id}
												onClick$={async (event) => {
													const opened = event.detail === 2;
													editing.value = opened
														? todo.id
														: editing.value;
													editDraft.value = opened
														? todo.title
														: editDraft.value;
													await props.onTrace$(
														'edit',
														{ id: todo.id, opened },
														event,
													);
												}}
											>
												{todo.title}
											</button>
											<button
												type="button"
												class="destroy"
												data-destroy={todo.id}
												onClick$={async (event) => {
													todos.splice(
														0,
														todos.length,
														...todos.filter(
															(entry) => entry.id !== todo.id,
														),
													);
													await props.onTrace$(
														'destroy',
														{ id: todo.id },
														event,
													);
												}}
											>
												x
											</button>
										</div>
									)}
								</li>
							))}
						</ul>
					</main>
				) : null}
				{todos.length > 0 ? (
					<footer class="footer">
						<span class="todo-count">
							<strong>{active.value}</strong>
							{remainingLabel.value}
						</span>
						<ul class="filters">
							<li>
								<a
									href="#/"
									data-filter="all"
									class={filter.value === 'all' ? 'selected' : ''}
									onClick$={[
										sync$((event) => {
											event.preventDefault();
										}),
										$(async (event) => {
											filter.value = 'all';
											await props.onTrace$(
												'filter',
												{ filter: 'all' },
												event,
											);
										}),
									]}
								>
									All
								</a>
							</li>
							<li>
								<a
									href="#/active"
									data-filter="active"
									class={filter.value === 'active' ? 'selected' : ''}
									onClick$={[
										sync$((event) => {
											event.preventDefault();
										}),
										$(async (event) => {
											filter.value = 'active';
											await props.onTrace$(
												'filter',
												{ filter: 'active' },
												event,
											);
										}),
									]}
								>
									Active
								</a>
							</li>
							<li>
								<a
									href="#/completed"
									data-filter="completed"
									class={filter.value === 'completed' ? 'selected' : ''}
									onClick$={[
										sync$((event) => {
											event.preventDefault();
										}),
										$(async (event) => {
											filter.value = 'completed';
											await props.onTrace$(
												'filter',
												{ filter: 'completed' },
												event,
											);
										}),
									]}
								>
									Completed
								</a>
							</li>
						</ul>
						{completed.value > 0 ? (
							<button
								type="button"
								class="clear-completed"
								data-action="clear-completed"
								onClick$={async (event) => {
									const cleared = todos.filter((todo) => todo.done).length;
									todos.splice(
										0,
										todos.length,
										...todos.filter((todo) => !todo.done),
									);
									await props.onTrace$('clear-completed', { cleared }, event);
								}}
							>
								Clear completed
							</button>
						) : null}
					</footer>
				) : null}
			</section>
		);
	},
);
